import React from "react";
import "./Photos.css";

export default function Photos(props) {
  console.log(props.photos);
  if (props.photos) {
    return (
      <section className="Photos">
        <div className="row">
          {" "}
          {props.photos.map(function (photo, index) {
            return (
              <div>
                {" "}
                <img src={photo.src.tiny} key={index}></img>{" "}
              </div>
            );
          })}
        </div>
      </section>
    );
  } else {
    return null;
  }
}
